SELECT b.id, b.type, b.serial_number, b.bom_version AS version, b.STATE, b.remark, b.create_time, b.create_user_id, b.update_time, bs.sku_no, bs.quantity, bs.parent_sku_no FROM product_bom_sku bs LEFT JOIN product_bom_info b ON bs.bom_id = b.id AND b.is_deleted = FALSE WHERE ${params.sqlMap.default} AND bs.is_deleted = FALSE
AND b.id IN
#{id}
AND ( bs.sku_id IN
#{skuId}
OR bs.parent_sku_id IN
#{skuId}
)
AND b.state IN
#{state}
${params.permissionSql}
ORDER BY b.create_time DESC

SELECT serial_number,id AS bomId FROM product_bom_info WHERE is_deleted = FALSE
AND id IN
#{id}

SELECT b.id, b.type, b.serial_number, b.bom_version AS version, b.STATE, b.remark, b.create_time, b.create_user_id, b.update_time, bs.sku_no, bs.parent_sku_no, bs.quantity FROM product_bom_sku bs LEFT JOIN product_bom_info b ON bs.bom_id = b.id AND b.is_deleted = FALSE WHERE ${params.sqlMap.default} AND bs.is_deleted = FALSE
AND b.id IN
#{id}
AND ( bs.sku_id IN
#{skuId}
OR bs.parent_sku_id IN
#{skuId}
)
